{"tool": "write", "path": "reports/export.py", "content": """"Reports CSV exporter. Implement export_csv to satisfy TASK.txt."""


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header.

    rows: iterable of mappings; columns: ordered iterable of unique string
    names. Returns a str with header plus one record per row, CRLF endings,
    minimal quoting with quote doubling. Missing fields and None become empty
    strings; other values are passed through str(). Unselected fields are
    ignored. Inputs are not mutated; one-shot generators are supported.
    """
    cols = list(columns)
    for c in cols:
        if not isinstance(c, str):
            raise ValueError("column names must be strings: %r" % (c,))
    if len(set(cols)) != len(cols):
        raise ValueError("duplicate column names: %r" % (cols,))

    lines = []

    def render_record(values):
        out = []
        for v in values:
            if v is None:
                v = ""
            elif not isinstance(v, str):
                v = str(v)
            if any(ch in v for ch in ("\r", "\n", '"', ",")):
                v = '"' + v.replace('"', '""') + '"'
            out.append(v)
        return ",".join(out)

    lines.append(render_record(cols))
    for row in rows:
        lines.append(render_record(row.get(c) for c in cols))
    return "\r\n".join(lines) + "\r\n"
